<?php $this->assign('title', 'Venda rápida'); ?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Venda rápida</h1><span class="badge text-bg-<?= $caixa ? 'success' : 'danger' ?>"><?= $caixa ? 'Caixa aberto' : 'Caixa fechado' ?></span></div><div class="card card-body border-0 shadow-sm"><?= $this->Form->create() ?><div class="row g-3"><div class="col-md-6"><?= $this->Form->control('cliente_id', ['options' => $clientes, 'empty' => 'Consumidor', 'class' => 'form-select']) ?></div><div class="col-md-6"><?= $this->Form->control('medicamento_id', ['options' => $medicamentos, 'empty' => 'Nenhum medicamento', 'class' => 'form-select']) ?></div><div class="col-md-6"><?= $this->Form->control('produto_id', ['options' => $produtos, 'empty' => 'Nenhum produto', 'class' => 'form-select']) ?></div><div class="col-md-6"><?= $this->Form->control('receita_id', ['options' => $receitas, 'empty' => 'Sem receita', 'class' => 'form-select']) ?></div><div class="col-md-3"><?= $this->Form->control('quantidade', ['type' => 'number', 'step' => '.001', 'min' => '.001', 'class' => 'form-control']) ?></div><div class="col-md-3"><?= $this->Form->control('desconto', ['type' => 'number', 'step' => '.01', 'min' => 0, 'class' => 'form-control']) ?></div><div class="col-md-3"><?= $this->Form->control('acrescimo', ['type' => 'number', 'step' => '.01', 'min' => 0, 'class' => 'form-control']) ?></div><div class="col-md-3"><?= $this->Form->control('forma', ['options' => ['dinheiro' => 'Dinheiro', 'pix' => 'PIX', 'debito' => 'Débito', 'credito' => 'Crédito', 'convenio' => 'Convênio'], 'class' => 'form-select']) ?></div><div class="col-md-4"><?= $this->Form->control('valor_pago', ['type' => 'number', 'step' => '.01', 'class' => 'form-control']) ?></div><div class="col-md-8"><?= $this->Form->control('referencia', ['class' => 'form-control']) ?></div></div><?= $this->Form->button('Finalizar venda', ['class' => 'btn btn-primary mt-4', 'disabled' => !$caixa]) ?><?= $this->Form->end() ?></div>
